const clamp=(v,lo,hi)=>Math.max(lo,Math.min(hi,v));
function preview(r,lane){return r?.preview?.racers?.[String(lane)]||{}}
function exhibitionScores(r){const rs=Object.entries(r.racers||{}).sort((a,b)=>+a[0]-+b[0]),out={};rs.forEach(([k])=>out[k]=0);for(const[f,w]of[['exhibition_time',30],['start_timing',25],['lap_time',20],['turn_time',15],['straight_time',10]]){const vals=rs.map(([k])=>[k,preview(r,k)?.[f]]).filter(z=>z[1]!=null&&z[1]!==''&&Number.isFinite(Number(z[1]))&&Number(z[1])>=0).map(z=>[z[0],Number(z[1])]);if(vals.length<2)continue;const a=vals.map(z=>z[1]),hi=Math.max(...a),lo=Math.min(...a);for(const[k,x]of vals)out[k]+=(hi===lo?.5:(hi-x)/(hi-lo))*w}return out}
function exhibitionFactors(r,rows){const sc=exhibitionScores(r),vals=rows.map(z=>sc[z.k]).filter(Number.isFinite);if(vals.length<2)return rows.map(()=>1);const avg=vals.reduce((a,b)=>a+b,0)/vals.length;return rows.map(z=>Number.isFinite(sc[z.k])?clamp(1+(sc[z.k]-avg)*.002,.94,1.06):1)}
const weighted=p=>p[0]*.5+p[1]*.3+p[2]*.2;
function makeBets(rows,max=6,mode='hit'){const strength=new Map(rows.slice().sort((a,b)=>weighted(b.p)-weighted(a.p)).map((z,i)=>[z.k,i]));let all=[];for(const x of rows)for(const y of rows)for(const z of rows){if(x.k===y.k||x.k===z.k||y.k===z.k)continue;const rr=Math.max(1e-12,x.p[0])*Math.max(1e-12,y.p[1])*Math.max(1e-12,z.p[2]),r1=strength.get(x.k)||0,r2=strength.get(y.k)||0,r3=strength.get(z.k)||0,hole=(r1*.55+r2*.28+r3*.17)/5,score=Math.pow(rr,.68)*(1+hole*1.15);all.push({combo:`${x.k}-${y.k}-${z.k}`,boats:[x.k,y.k,z.k],ranks:[r1,r2,r3],raw:rr,score:mode==='return'?score:rr,hole})}all.sort((a,b)=>b.raw-a.raw);let top;if(mode==='balance'){const pool=all.slice(0,40),chosen=[];while(chosen.length<Math.min(max,pool.length)){let best,bv=-1;for(const bet of pool){if(chosen.some(c=>c.combo===bet.combo))continue;const base=bet.raw/(pool[0]?.raw||1),novel=bet.boats.reduce((s,boat,pos)=>s+(chosen.some(c=>c.boats[pos]===boat)?0:[.55,.3,.15][pos]),0),v=base*.58+novel*.42;if(v>bv){bv=v;best=bet}}if(!best)break;chosen.push({...best,score:bv})}top=chosen}else if(mode==='return'){const br=all[0]?.raw||1,pool=all.filter(b=>b.raw>=br*.08&&b.hole>=.1).sort((a,b)=>b.score-a.score),outs=pool.filter(b=>b.ranks[0]>=1).slice(0,Math.ceil(max*.67)),fav=pool.filter(b=>b.ranks[0]===0&&!outs.some(x=>x.combo===b.combo)).slice(0,max-outs.length);top=[...outs,...fav].sort((a,b)=>b.score-a.score);if(top.length<max)top.push(...pool.filter(b=>!top.some(x=>x.combo===b.combo)).slice(0,max-top.length))}else{const favorite=rows.slice().sort((a,b)=>b.p[0]-a.p[0])[0]?.k,safe=all.filter(b=>b.boats[0]===favorite&&b.ranks[1]<=3&&b.ranks[2]<=4);top=(safe.length>=max?safe:all.filter(b=>b.boats[0]===favorite)).slice(0,max)}const sum=top.reduce((s,b)=>s+b.score,0)||1;return top.map((b,i)=>({...b,share:b.score/sum,rank:i+1}))}
export {exhibitionScores,exhibitionFactors,makeBets as engineMakeBets};
